package dev.interview.orders.config;
import org.slf4j.*; import org.springframework.cache.*; import org.springframework.cache.annotation.EnableCaching; import org.springframework.cache.interceptor.CacheErrorHandler; import org.springframework.context.annotation.*; import org.springframework.data.redis.cache.*; import org.springframework.data.redis.serializer.*; import java.time.Duration;
@Configuration @EnableCaching public class CacheConfig {
 @Bean RedisCacheConfiguration redisCacheConfiguration(){return RedisCacheConfiguration.defaultCacheConfig().entryTtl(Duration.ofMinutes(5)).disableCachingNullValues().serializeValuesWith(RedisSerializationContext.SerializationPair.fromSerializer(new GenericJackson2JsonRedisSerializer()));}
 @Bean CacheErrorHandler cacheErrorHandler(){return new CacheErrorHandler(){private final Logger log=LoggerFactory.getLogger("cache");public void handleCacheGetError(RuntimeException e,Cache c,Object k){log.warn("cache_get_failed cache={} key={}",c.getName(),k);}public void handleCachePutError(RuntimeException e,Cache c,Object k,Object v){log.warn("cache_put_failed cache={} key={}",c.getName(),k);}public void handleCacheEvictError(RuntimeException e,Cache c,Object k){log.warn("cache_evict_failed cache={} key={}",c.getName(),k);}public void handleCacheClearError(RuntimeException e,Cache c){log.warn("cache_clear_failed cache={}",c.getName());}};}
}
